const currentUser = localStorage.getItem("currentUser");
if (!currentUser) window.location.href = "../login/index.html";

// 백엔드 주소 세팅 (main.js와 동일하게 적용)
const BACKEND_URL = window.location.hostname === 'localhost' ? 'http://localhost:7860/' : 'https://uzaramen108-paper-backend.hf.space/';

document.getElementById("user-display").textContent = currentUser;

let papersMeta = {};
let userPrefs = { sort: "desc", favorites: [], hidden: [] };

async function loadManagementData() {
    // 1. 유저 설정 불러오기 (임시: 백엔드 API 대신 로컬스토리지 활용으로 즉각 반응)
    const storedPrefs = localStorage.getItem(`prefs_${currentUser}`);
    if (storedPrefs) userPrefs = JSON.parse(storedPrefs);
    document.getElementById("sort-select").value = userPrefs.sort;

    // 2. 전체 논문 메타데이터 불러오기
    try {
        const res = await fetch(`${BACKEND_URL}api/papers_meta`); // 백엔드에 이 API 추가 필요
        if (res.ok) papersMeta = await res.json();
        renderList();
    } catch (err) {
        console.error("논문 목록을 불러오지 못했습니다.");
    }
}

function renderList() {
    const container = document.getElementById("management-list");
    container.innerHTML = "";

    Object.entries(papersMeta).forEach(([filename, meta]) => {
        const row = document.createElement("div");
        row.className = "paper-row";
        
        const isFav = userPrefs.favorites.includes(filename);
        const isHidden = userPrefs.hidden.includes(filename);
        const isMine = meta.uploader === currentUser;

        row.innerHTML = `
            <div>
                <strong>[No.${meta.id}]</strong> ${filename}<br>
                <span style="font-size: 0.85em; color: #666;">투고자: ${meta.uploader} | ${meta.date}</span>
            </div>
            <div class="controls">
                <button class="btn-fav ${isFav ? 'active-fav' : ''}" onclick="togglePref('favorites', '${filename}')">⭐ 즐겨찾기</button>
                <button class="btn-hide ${isHidden ? 'active-hide' : ''}" onclick="togglePref('hidden', '${filename}')">🙈 숨기기</button>
                ${isMine ? `<button class="btn-delete" onclick="deletePaper('${filename}')">🗑️ 삭제</button>` : ''}
            </div>
        `;
        container.appendChild(row);
    });
}

function togglePref(type, filename) {
    const idx = userPrefs[type].indexOf(filename);
    if (idx > -1) userPrefs[type].splice(idx, 1);
    else userPrefs[type].push(filename);
    
    // 설정 저장 (백엔드에 저장하는 API 호출 추가 추천, 현재는 로컬스토리지)
    localStorage.setItem(`prefs_${currentUser}`, JSON.stringify(userPrefs));
    renderList();
}

async function deletePaper(filename) {
    if (!confirm(`정말 '${filename}' 논문을 삭제하시겠습니까? (복구 불가)`)) return;
    
    try {
        const res = await fetch(`${BACKEND_URL}api/paper/${filename}?requester=${currentUser}`, { method: "DELETE" });
        if (res.ok) {
            alert("삭제되었습니다.");
            delete papersMeta[filename];
            renderList();
        } else {
            alert("삭제 실패: 권한이 없습니다.");
        }
    } catch (err) { alert("서버 오류"); }
}

document.getElementById("sort-select").addEventListener("change", (e) => {
    userPrefs.sort = e.target.value;
    localStorage.setItem(`prefs_${currentUser}`, JSON.stringify(userPrefs));
});

loadManagementData();